    if($('#installUpdate'))$('#installUpdate').onclick=()=>{if(!updateState.ready)return;confirm('模拟安装并重启','这里只演示确认与成功反馈，不会安装、退出或重启任何应用。',()=>notify('安装交接已模拟，未更改系统。'));};if($('#rollback'))$('#rollback').onclick=()=>confirm('模拟回滚','当前编辑不会自动保存。这里仅展示确认，不访问安装目录。',()=>notify('回滚已模拟，未更改系统。'));
