  function saveSettingsDraft(){if($('#settingBackend')){S.settings.backend=$('#settingBackend').value;S.settings.client=$('#settingClient').value;S.settings.snap=$('#settingSnap').checked;const key=$('#settingHotkey').value.trim();if(key)S.settings.hotkey=key;}if($('#serviceName')){const service=S.services.find(s=>s.id===S.serviceId);if(service){service.name=$('#serviceName').value.trim()||'未命名服务';service.model=$('#serviceModel').value.trim()||'demo-model';}}}
  function renderSystemState(){if($('#updateMessage'))$('#updateMessage').textContent=updateState.status;if($('.update-progress i'))$('.update-progress i').style.width=updateState.progress+'%';if($('#installUpdate'))$('#installUpdate').disabled=!updateState.ready;if($('#serviceMessage'))$('#serviceMessage').textContent=serviceMessage;}
  function systemOperation(kind){if(systemTask)return;const outcome=$('#outcome').value,ms=outcome==='slow'?4300:kind==='download'?1800:900;const task={id:uid(),kind,start:performance.now(),timer:0};systemTask=task;updateState.ready=false;task.timer=setInterval(()=>{if(systemTask!==task)return;const p=Math.min(100,(performance.now()-task.start)/ms*100);if(kind==='service')serviceMessage='连接测试中（模拟）…';else{updateState.progress=p;updateState.status=kind==='check'?'检查更新中（模拟）…':`模拟下载 ${Math.floor(p)}%`;}if(p===100){clearInterval(task.timer);systemTask=null;if(outcome==='failure'){if(kind==='service')serviceMessage='连接失败（模拟），配置未丢失。';else updateState.status='操作失败（模拟），可以重试。';}else if(kind==='service')serviceMessage='模拟连接成功，不代表真实接口可用。';else if(kind==='check')updateState.status='发现示例新版本 0.4.11';else{updateState.status='模拟下载与完整性检查完成';updateState.ready=true;}}renderSystemState();},60);}
  const savedProjects=[];
  function openHistory(){openModal('本次演示的手动项目',`<p>没有自动保存。只有你手动保存的演示项目会出现在这里，刷新页面即清空此列表。</p><div id="historyList">${savedProjects.length?savedProjects.map((p,i)=>`<div class="history-row"><span>${esc(p.name)}<small>${p.time}</small></span><button class="secondary" data-restore="${i}">恢复</button><button class="danger" data-delete-project="${i}">删除</button></div>`).join(''):'<div class="empty-note">尚无手动保存的项目。</div>'}</div>`);$$('[data-restore]').forEach(b=>b.onclick=()=>{cancelTask(false);S.docId++;S.revision=0;S.epoch++;apply(savedProjects[Number(b.dataset.restore)].data);resetHistory();phase('editing');$('#hiddenState').hidden=true;closeModal();L.enter();});$$('[data-delete-project]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.deleteProject);confirm('删除演示记录','只删除当前页面内的记录，下载的项目文件不会被删除。',()=>{savedProjects.splice(i,1);openHistory();});});}
  function openComponents(){openModal('基础组件与状态',`<p>沿用同一材质，降低运动强度。表单内容不随指针漂移。</p><div class="component-grid"><section class="component-group"><h3>动作 / 可用性</h3><div class="button-row"><button class="primary" id="componentSuccess">成功反馈</button><button class="secondary" id="componentError">错误反馈</button></div><div class="button-row"><button class="secondary" disabled>不可用</button><button class="secondary" id="componentBusy">等待与取消</button></div></section><section class="component-group"><h3>输入 / 选择</h3><label class="field">示例输入<input placeholder="可以输入文字"></label><label class="field">输出尺寸<select><option>1× 原始尺寸</option><option>2× 放大输出</option></select></label></section><section class="component-group"><h3>连续 / 二元状态</h3><label class="range-label">示例强度<output id="componentRangeLabel">50%</output><input id="componentRange" type="range" value="50"></label><label class="switch">启用示例选项<input type="checkbox" checked><span></span></label><details><summary>展开说明</summary><p>同一控件不因切换展开状态丢失焦点；文本保持清晰。</p></details></section><section class="component-group"><h3>确认 / 条款</h3><button class="secondary" id="componentTerms">首次使用条款</button><div class="button-row"><button class="danger" id="componentDanger">删除确认</button></div><span class="status-pill">就绪</span><span class="status-pill">处理中</span><span class="status-pill">需重试</span></section></div>`);$('#componentSuccess').onclick=()=>modalFeedback('操作成功，状态已更新。');$('#componentError').onclick=()=>modalFeedback('操作失败：保留现场，可继续重试。',true);$('#componentRange').oninput=e=>$('#componentRangeLabel').textContent=e.target.value+'%';$('#componentBusy').onclick=e=>{const b=e.currentTarget;if(b.dataset.pending){clearTimeout(Number(b.dataset.pending));delete b.dataset.pending;b.textContent='等待与取消';modalFeedback('等待已取消');return;}b.textContent='处理中 · 点击取消';b.dataset.pending=setTimeout(()=>{if(!b.isConnected)return;delete b.dataset.pending;b.textContent='等待与取消';modalFeedback('模拟处理完成');},1800);};$('#componentTerms').onclick=openTerms;$('#componentDanger').onclick=()=>confirm('确认删除','只是演示，不会删除真实文件。',()=>openComponents());}
  function modalFeedback(text,error=false){const body=$('.modal-body');if(!body)return;let e=body.querySelector('.inline-feedback');if(!e){e=document.createElement('div');e.className='notice-inline inline-feedback';body.prepend(e);}e.textContent=text;e.classList.toggle('error',error);e.setAttribute('role',error?'alert':'status');}
  function openTerms(){openModal('使用条款 · 交互示例',`<p>这是首次启动确认的交互替身，不是正式法律文本。</p><div class="notice-inline" style="max-height:170px;overflow:auto">本原型只在本地演示交互。不会读取真实屏幕、注册系统热键、向模型发送请求、收集 API 密钥或修改安装。<br><br>用户主动导入的图片仅供当前页面编辑，关闭页面后不会自动恢复。保存演示项目可能包含图片原始像素，请自行保管。<br><br>正式应用的条款、许可、隐私与安全边界仍由正式应用提供。</div><label class="switch">我已阅读本次演示说明<input id="termsAgree" type="checkbox"><span></span></label><div class="modal-actions"><button class="secondary" id="termsDecline">不同意并关闭</button><button class="primary" id="termsAccept" disabled>同意并继续</button></div>`);$('#termsAgree').onchange=e=>$('#termsAccept').disabled=!e.target.checked;$('#termsDecline').onclick=()=>closeModal();$('#termsAccept').onclick=()=>{closeModal();notify('演示确认已完成，未记录法律同意。');};}
  function menuAction(action){closePopover();if(['new','open-image','open-project'].includes(action))closePanel(false);if(action==='new')resetCapture();if(action==='open-image')$('#imageFile').click();if(action==='open-project')$('#projectFile').click();if(action==='save-project')saveProject();if(action==='export')exportPng();if(action==='history')openHistory();if(action==='settings')openSettings();if(action==='components')openComponents();if(action==='reset-tools'){S.manualRail=S.manualPanel=false;positionRail();positionPanel();notify('工具位置已重置。');}}
