  function drawMarks(ctx,pad){ctx.save();ctx.translate(pad,pad);ctx.beginPath();ctx.rect(0,0,S.docW,S.docH);ctx.clip();for(const m of S.marks){ctx.save();ctx.strokeStyle=ctx.fillStyle=m.color;ctx.lineWidth=m.width;ctx.lineCap='round';ctx.lineJoin='round';if(m.type==='text'){ctx.font=`${m.fontSize}px 'Microsoft YaHei UI',sans-serif`;ctx.fillText(m.text,m.x,m.y);}else if(m.type==='arrow'){const dx=m.x2-m.x,dy=m.y2-m.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len,k=Math.max(10,m.width*3);ctx.beginPath();ctx.moveTo(m.x,m.y);ctx.lineTo(m.x2,m.y2);ctx.moveTo(m.x2-ux*k-uy*k*.5,m.y2-uy*k+ux*k*.5);ctx.lineTo(m.x2,m.y2);ctx.lineTo(m.x2-ux*k+uy*k*.5,m.y2-uy*k-ux*k*.5);ctx.stroke();}else{const r=bbox(m);if(m.type==='rect'){round(ctx,r.x,r.y,r.w,r.h,3);ctx.stroke();}else{if(m.type==='highlight')ctx.globalAlpha=.4;ctx.fillRect(r.x,r.y,r.w,r.h);}}ctx.restore();}ctx.restore();}
  function exportCanvas(scale=1){if(!S.image)throw new Error('暂无可导出的图片。');const w=Math.round((S.docW+S.style.pad*2)*scale),h=Math.round((S.docH+S.style.pad*2)*scale);if(w*h>T.demo.maxImagePixels)throw new Error('输出超过 2400 万像素，请减小倍率或留白。');const c=document.createElement('canvas');c.width=w;c.height=h;const q=c.getContext('2d');drawImageLayer(q,scale);q.scale(scale,scale);drawMarks(q,S.style.pad);return c;}
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportPng(){try{const c=exportCanvas(S.exportScale);c.toBlob(blob=>{if(blob)download(blob,'Screenshot-liquid.png');else notify('无法编码 PNG，当前编辑已保留。',true);},'image/png');}catch(e){notify(e.message,true);}}
