  function resetDocument(){cancelTask(false);S.epoch++;fileSerial++;cancelExit();closePanel(false);closeReader(false);closeModal(false);closePopover();finishText(true);const r=makeDesktop();S.docId++;S.revision=0;S.r=r;setImage(crop(r));S.style=neutral();S.marks=[];S.selected=null;S.tool='select';S.sourceText=S.translatedText=S.translationBasis='';S.imageTranslated=false;S.translationBlocks=[];S.manualRail=S.manualPanel=false;S.readerBounds=null;resetHistory();phase('editing');$('#hiddenState').hidden=true;render();L.enter();L.pulse(viewRect());}
  function hideTip(){clearTimeout(tipTimer);$('#tooltip').hidden=true;}
